+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A-Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <span class="text-muted small">
+                    Showing @firstItem–@lastItem of @result.TotalCount products
+                </span>
+            </div>
+
+            @* Product Grid *@
+            <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
+                @foreach (var product in result.Items)
+                {
+                    <div class="col">
+                        <div class="card h-100 product-card" @onclick="() => OnProductSelected(product)"
+                             role="button" tabindex="0">
+                            <div class="card-img-top product-image-placeholder d-flex align-items-center justify-content-center bg-light"
+                                 role="img" aria-label="@product.Name">
+                                <span class="text-muted">@product.Name</span>
+                            </div>
+                            <div class="card-body d-flex flex-column">
